import { useState } from "react";
import apiAxios from "../config/axiosConfig";
import { useHistory } from "react-router-dom";


const Secret = () => {
        const history = useHistory()
        const [msg, setMsg] = useState("")


        const handleSecuredRoute = async () => {
                try {
                        const response = await apiAxios.get("/secured-route", {withCredentials:true})
                        if (response.status === 200) {
                                setMsg(response.data)
                                history.push
                        }
                } catch (error) {
                        console.log(error)
                        setMsg(error)
                }
        }

        const handleLogout = async (req, res) => {
                try {
                        await apiAxios.post("/auth/logout", {withCredentials:true})
                        
                } catch (error) {
                        console.log("b ", error)
                        setMsg(error)
                }
        }

        return ( 
                <div>
                        <button onClick={handleSecuredRoute}>Enter secured route</button>
                        <button onClick={handleLogout}>Logout</button>
                        {msg}
                </div>
         );
}
 

export default Secret;
